power_user.custom_css:
.mes_block {
    --avatar-size: 600px; /* Cambia este número para hacerlo más grande */
}

.pwa_avatars_block img,
.mes_avatar img {
    width: var(--avatar-size) !important;
    height: var(--avatar-size) !important;
    max-width: var(--avatar-size) !important;
    max-height: var(--avatar-size) !important;
}

/* VN: legibilidad y acentos */
#chat .mes_text {
    color: rgba(226, 222, 212, 1);
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9), 0 0 14px rgba(0, 0, 0, 0.5);
    font-size: 16px;
    line-height: 1.55;
}
#chat .mes_text em {
    color: rgba(170, 164, 152, 1);
}
#chat .mes_text strong {
    color: rgba(206, 172, 121, 1);
}
#send_textarea {
    color: rgba(230, 226, 216, 1);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.8);
}

